// DingoNodes: header afterRender JS (shared suite prelude + this dashboard's KPIs)
(function () {
  var ROOT_ID = 'hx-dingonodes';
  try {

  var s = (context && context.panelData && context.panelData.series) ? context.panelData.series : [];
  function lastv(v) { if (!v) return undefined; for (var i = v.length - 1; i >= 0; i--) { var x = v[i]; if (x !== null && x !== undefined && isFinite(x)) return Number(x) } return undefined }
  /* rows(ref): [{l: labels, v: last value}] for every series of that query */
  function rows(ref) {
    var out = [];
    for (var si = 0; si < s.length; si++) {
      if (!s[si] || s[si].refId !== ref) continue;
      var f = s[si].fields || [];
      for (var j = 0; j < f.length; j++) {
        if (f[j].type !== 'number') continue;
        var v = lastv(f[j].values && f[j].values.toArray ? f[j].values.toArray() : f[j].values);
        if (v !== undefined) out.push({ l: f[j].labels || {}, v: v });
      }
    }
    return out;
  }
  function one(ref) { var r = rows(ref); return r.length ? r[0].v : undefined }
  function sum(ref) { var r = rows(ref), t = 0; for (var i = 0; i < r.length; i++) t += r[i].v; return r.length ? t : undefined }
  function minRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v < m.v) m = r[i]; return m }
  function maxRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v > m.v) m = r[i]; return m }
  function byLabel(ref, label) { var r = rows(ref), o = {}; for (var i = 0; i < r.length; i++) { var k = r[i].l[label]; if (k !== undefined) o[k] = r[i].v } return o }
  function has(x) { return x !== undefined && x !== null && isFinite(x) }
  function n0(x) { return has(x) ? String(Math.round(x)) : '–' }
  function ms(sec) { if (!has(sec)) return '–'; var m = sec * 1000; return m >= 10000 ? (m / 1000).toFixed(1) + ' s' : (m >= 100 ? Math.round(m) : (m >= 10 ? m.toFixed(0) : m.toFixed(1))) + ' ms' }
  function plural(n, one_, many) { return n + ' ' + (n === 1 ? one_ : many) }
  function names(a, max) { max = max || 3; return a.length <= max ? a.join(', ') : a.slice(0, max).join(', ') + ' +' + (a.length - max) }
  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
  var RANK = { na: 0, ok: 1, warn: 2, bad: 3 };
  function worst(a, b) { return RANK[b] > RANK[a] ? b : a }
  /* lower is better: ok under w, warn under b, else bad */
  function low(x, w, b) { return !has(x) ? 'na' : (x < w ? 'ok' : (x < b ? 'warn' : 'bad')) }
  /* higher is better: ok at or above g, warn at or above a, else bad */
  function high(x, g, a) { return !has(x) ? 'na' : (x >= g ? 'ok' : (x >= a ? 'warn' : 'bad')) }
  function el(id) { return document.getElementById(id) }
  var root = el(ROOT_ID);
  /* light theme: ask Grafana, else infer it from the inherited text colour (dark text = light theme) */
  try {
    var th = context.grafana && context.grafana.theme, light = null;
    if (th && typeof th.isDark === 'boolean') light = !th.isDark;
    if (light === null && root && typeof getComputedStyle === 'function') {
      var m = /(\d+)[, ]+(\d+)[, ]+(\d+)/.exec(getComputedStyle(root).color || '');
      if (m) light = (0.299 * m[1] + 0.587 * m[2] + 0.114 * m[3]) < 128;
    }
    if (root && light && String(root.className).indexOf('hx-light') < 0) root.className += ' hx-light';
  } catch (e) { }
  /* fit(): a dynamic-text panel scrolls inside itself when its content is taller than the panel, and that
     captures the page scroll. Find the scrolling ancestor and, while the content overflows it, step through the
     compact levels (hx-fit1 drops the detail line, hx-fit2 also thins the rows and drops the legend). */
  function fit() {
    try {
      if (!root || !root.parentElement || typeof getComputedStyle !== 'function') return;
      root.className = String(root.className).replace(/ hx-fit\d/g, '');
      var box = root.parentElement, found = false;
      /* only a scroller inside this panel counts: stop at the panel chrome (<section>) or the grid item */
      while (box && box !== document.body) {
        var cls = typeof box.className === 'string' ? box.className : '';
        if (box.tagName === 'SECTION' || cls.indexOf('react-grid-item') >= 0) break;
        var oy = getComputedStyle(box).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && box.clientHeight > 0) { found = true; break }
        box = box.parentElement;
      }
      if (!found) return;
      for (var lvl = 1; lvl <= 2 && box.scrollHeight > box.clientHeight + 1; lvl++) root.className += ' hx-fit' + lvl;
    } catch (e) { }
  }
  function dur(sec) { if (!has(sec)) return '–'; var a = Math.abs(sec); if (a < 90) return Math.round(a) + ' s'; if (a < 5400) return Math.round(a / 60) + ' min'; if (a < 172800) return (a / 3600).toFixed(a < 36000 ? 1 : 0) + ' h'; return (a / 86400).toFixed(a < 864000 ? 1 : 0) + ' d' }
  var overall = 'na';
  /* kpi(key, value, unit, status, note): fill one tile; value '–' when undefined */
  function kpi(key, value, unit, status, note) {
    var t = el(ROOT_ID + '-k-' + key); if (!t) return;
    var miss = value === undefined || value === null || value === '–';
    var st = miss ? 'na' : (status || 'na');
    t.setAttribute('data-s', st);
    var c = t.children;
    if (c[1]) c[1].innerHTML = miss ? '–' : esc(value) + (unit ? '<small>' + esc(unit) + '</small>' : '');
    if (c[2]) c[2].textContent = miss ? (note || 'no data') : (note || '');
    if (c[2]) c[2].title = miss ? '' : (note || '');
    overall = worst(overall, st);
  }
  /* pills(list): one status pill per node, [{n: name, w: word, st: ok|warn|bad|na, t: tooltip, x: detail}] */
  function pills(list) {
    var c = el(ROOT_ID + '-pills'); if (!c) return;
    var order = { bad: 0, warn: 1, na: 2, ok: 3 };
    list.sort(function (a, b) { return (order[a.st] - order[b.st]) || String(a.n).localeCompare(String(b.n)) });
    c.innerHTML = list.map(function (p) {
      return '<span class="hx-pill" data-s="' + p.st + '" title="' + esc(p.t || '') + '"><i></i>' + esc(p.n) +
        ' <b>' + esc(p.w) + '</b>' + (p.x ? ' <small>' + esc(p.x) + '</small>' : '') + '</span>';
    }).join('');
  }
  function nodeName(l) { return l.pod || '?' }
  var BADGE = { ok: 'Healthy', warn: 'Attention', bad: 'Action needed', na: 'No data' };
  function verdict(html, status) {
    var st = status || overall;
    if (root) root.setAttribute('data-s', st);
    var b = el(ROOT_ID + '-badge'); if (b) b.lastChild.textContent = BADGE[st];
    var v = el(ROOT_ID + '-verdict'); if (v) v.innerHTML = html;
    fit();
  }

  var up = rows('UP'), gap = byLabel('GAP', 'pod');
  var total = up.length, down = [], syncing = [], lagging = [];
  for (var i = 0; i < up.length; i++) {
    var a = up[i].l.pod || '?';
    if (up[i].v < 1) { down.push(a); continue }
    if (gap[a] > 600) syncing.push(a); else if (gap[a] > 300) lagging.push(a);
  }
  var pStk = byLabel('STK', 'pod');
  pills(up.map(function (r) {
    var a = nodeName(r.l), g = gap[a];
    if (r.v < 1) return { n: a, w: 'Down', st: 'bad', t: 'Prometheus cannot scrape this Dingo' };
    if (has(pStk[a])) return { n: a, w: 'Stalled', st: 'bad', t: 'ledger pipeline stuck or halted' };
    if (g > 600) return { n: a, w: 'Syncing', st: 'warn', x: n0(g) + ' slots', t: n0(g) + ' slots behind the wall clock' };
    if (g > 300) return { n: a, w: 'Behind', st: 'warn', x: n0(g) + ' slots', t: n0(g) + ' slots behind the wall clock' };
    return { n: a, w: 'Synced', st: 'ok', t: has(g) ? n0(g) + ' slots from the wall-clock tip' : 'at tip' };
  }));
  var nUp = total - down.length, atTip = nUp - syncing.length;
  var issues = [], sev = 'ok';
  function issue(st, text) { issues.push({ st: st, text: text }); sev = worst(sev, st) }
  if (!total) { kpi('up'); kpi('tip') } else {
    kpi('up', nUp + '/' + total, '', down.length ? 'bad' : 'ok', down.length ? 'down: ' + names(down) : 'all scraped');
    kpi('tip', atTip + '/' + nUp, '', syncing.length ? 'warn' : (lagging.length ? 'warn' : 'ok'),
      syncing.length ? 'syncing: ' + names(syncing) : (lagging.length ? 'lagging: ' + names(lagging) : 'within 300 slots'));
  }
  if (down.length) issue('bad', '<b>' + esc(names(down)) + '</b> ' + (down.length === 1 ? 'is' : 'are') + ' down');
  var stuck = rows('STK').map(function (r) { return r.l.pod });
  if (stuck.length) issue('bad', 'ledger pipeline stuck on <b>' + esc(names(stuck)) + '</b>');
  if (syncing.length) issue('warn', '<b>' + esc(names(syncing)) + '</b> ' + (syncing.length === 1 ? 'is' : 'are') + ' syncing');
  if (lagging.length) issue('warn', '<b>' + esc(names(lagging)) + '</b> ' + (lagging.length === 1 ? 'is' : 'are') + ' over 300 slots behind');
  var arr = one('ARR');
  kpi('arr', has(arr) ? n0(arr) : undefined, 'ms', low(arr, 500, 1000), 'slot to header, p50 over 1 h');
  if (has(arr) && arr >= 500) issue(low(arr, 500, 1000), 'blocks arrive late (p50 <b>' + n0(arr) + ' ms</b>)');
  var kes = minRow(rows('KES'));
  kpi('kes', kes ? n0(kes.v) : undefined, 'periods', kes ? high(kes.v, 8, 4) : 'na', kes ? (kes.l.pod || '') + ' · ' + n0(kes.v * 1.5) + ' days' : '');
  if (kes && kes.v < 8) issue(high(kes.v, 8, 4), 'KES on <b>' + esc(kes.l.pod) + '</b> has ' + plural(Math.round(kes.v), 'period', 'periods') + ' left (rotation is due at 8)');
  var run = minRow(rows('RUN')), full = one('DSK');
  kpi('run', run ? (run.v >= 365 ? '> 1' : n0(run.v)) : undefined, run && run.v >= 365 ? 'year' : 'days', run ? high(run.v, 30, 7) : 'na',
    run ? (run.l.pod || '') + (has(full) ? ' · fullest disk ' + n0(full * 100) + '%' : '') : '');
  if (run && run.v < 30) issue(high(run.v, 30, 7), 'the data volume of <b>' + esc(run.l.pod) + '</b> fills in ' + plural(Math.round(run.v), 'day', 'days') + ' at the last 24 h rate');
  if (has(full) && full >= 0.85) issue('bad', 'a node disk is <b>' + n0(full * 100) + '%</b> full (kubelet evicts near 85%)');
  var thin = rows('THN').map(function (r) { return r.l.pod });
  if (thin.length) issue('warn', '<b>' + esc(names(thin)) + '</b> ' + (thin.length === 1 ? 'has' : 'have') + ' under 5 hot peers');
  var ver = rows('VER').map(function (r) { return String(r.l.version || '').replace(/^v/, '').split(' ')[0] });
  if (ver.length > 1) issue('warn', 'the pack runs ' + ver.length + ' versions (' + esc(names(ver)) + ')');
  var rst = rows('RST').filter(function (r) { return r.v >= 3 }).map(function (r) { return r.l.pod });
  if (rst.length) issue('warn', '<b>' + esc(names(rst)) + '</b> restarted 3 or more times in 24 h');
  if (!total) { verdict('No Dingo is being scraped on the selected networks.', 'na') }
  else if (!issues.length) {
    verdict('All ' + total + ' Dingos are up and at tip' + (ver.length === 1 ? ' on ' + esc(ver[0]) : '') +
      (has(arr) ? '; blocks arrive in ' + n0(arr) + ' ms' : '') + '; nothing expires or fills up within 30 days.', 'ok');
  } else {
    issues.sort(function (x, y) { return RANK[y.st] - RANK[x.st] });
    var txt = issues.slice(0, 3).map(function (x) { return x.text }).join('; ');
    if (issues.length > 3) txt += '; and ' + (issues.length - 3) + ' more';
    verdict(txt.charAt(0) === '<' ? txt + '. ' + atTip + ' of ' + total + ' Dingos are at tip.' : txt.charAt(0).toUpperCase() + txt.slice(1) + '. ' + atTip + ' of ' + total + ' Dingos are at tip.', sev);
  }

  } catch (e) {
    var v = document.getElementById(ROOT_ID + '-verdict');
    if (v) v.textContent = 'Header script error: ' + (e && e.message ? e.message : e);
  }
})();

