// DingoNodes: Block Lanes afterRender JS
// One lane per Dingo, grouped by network, the last hour before the end of the time range.
// One bar per block at its slot time; height = delay after the slot (linear to 1 s, log above).
// Grey = waiting for the header, colour = header to ledger adoption. A yellow dot marks the
// Dingo that heard the header first among the Dingos of that network. A syncing or down node
// gets a labelled lane instead of bars, so it never reads as a slow node.
(function () {
  var s = (context.panelData && context.panelData.series) ? context.panelData.series : [];
